-- [+] FUNCTION win_path
-- DEFINER 없이 생성합니다 — 실행한 사용자가 DEFINER 가 됩니다
SET @OLD_SQL_MODE = @@SQL_MODE, SQL_MODE = 'NO_BACKSLASH_ESCAPES,STRICT_TRANS_TABLES';
DELIMITER ;;
CREATE FUNCTION `win_path`() RETURNS varchar(20) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
    COMMENT 'C:\new it''s'
RETURN 'C:\temp';;
DELIMITER ;
SET SQL_MODE = @OLD_SQL_MODE;
